  "projectSettings.autoPropagateRepetitions.label": "Sambaza marudio kiotomatiki",
  "projectSettings.autoPropagateRepetitions.description": "Ikiwa kuthibitisha seli kunanakili tafsiri yake kwenda seli nyingine katika faili ile ile ambazo Source text yao ni sawa. Seli zilizojazwa huachwa bila kuthibitishwa, na seli ambazo mtu amekwisha kuzithibitisha hazibadilishwi kamwe.",
  "projectSettings.autoPropagateRepetitions.saveFailed": "Imeshindwa kuhifadhi mabadiliko hayo",
  "projectSettings.validation.allowSelfLabel": "Ruhusu kujithibitisha (maandishi)",
  "projectSettings.validation.allowSelfDescription": "Inapozimwa, hakuna mtu anayeweza kuthibitisha mstari ambao mabadiliko yake ya hivi karibuni ni yake mwenyewe, bila kujali jukumu lake. Mtu mwingine lazima athibitishe.",
  "projectSettings.validation.namedValidatorsLabel": "Wathibitishaji waliotajwa",
  "projectSettings.validation.namedValidatorsDescription": "Ikiwa kuna aliyeainishwa, watu hawa pekee ndio wanaweza kuthibitisha maandishi, na bado wanahitaji jukumu la chini hapo juu. Acha wazi ili kuruhusu yeyote anayetimiza jukumu la chini.",
  "projectSettings.validation.minRoleAudioLabel": "Jukumu la chini la kuthibitisha rekodi",
  "projectSettings.validation.minRoleAudioDescription": "Nani anayeweza kuthibitisha rekodi. Inawekwa kando na kanuni ya maandishi hapo juu — mradi unaweza kutaka kiwango cha juu zaidi kwa sauti kuliko kwa tafsiri, au kinyume chake.",
  "projectSettings.validation.allowSelfAudioLabel": "Ruhusu kuthibitisha rekodi zako mwenyewe",
  "projectSettings.validation.allowSelfAudioDescription": "Inapozimwa, aliyerekodi toleo hawezi kulithibitisha — mtu mwingine lazima asikilize. Matoleo ambayo hajulikani nani aliyerekodi hayaathiriwi, hivyo rekodi za zamani haziwi kamwe zisizowezekana kuthibitisha.",
  "projectSettings.validation.namedValidatorsAudioLabel": "Wathibitishaji waliotajwa wa rekodi",
  "projectSettings.validation.namedValidatorsAudioDescription": "Ikiwa kuna aliyeainishwa, watu hawa pekee ndio wanaweza kuthibitisha rekodi. Acha wazi ili kuruhusu yeyote anayetimiza jukumu la chini hapo juu.",
  "projectSettings.decay.summary": "Afya",
  "projectSettings.decay.description": "Ishara hii ya afya hupima ukaribu na seli jirani zilizoidhinishwa katika grafu ya urejeshaji. Inaweza kusaidia kupanga kipaumbele cha ukaguzi, lakini si alama ya ubora wa tafsiri, na haiwai kuondoa sharti la ukaguzi wa binadamu.",
  "projectSettings.decay.maxHopsLabel": "Upeo wa kuruka",
  "projectSettings.decay.maxHopsDescription": "Umbali wa usambazaji kutoka seli zilizoidhinishwa. Thamani kubwa zaidi huruhusu afya kuenea zaidi katika grafu ya urejeshaji. Chaguo-msingi {defaultValue}.",
  "projectSettings.decay.attentionThresholdLabel": "Kizingiti cha umakini",
  "projectSettings.decay.attentionThresholdDescription": "Afya ya chini ikipita kizingiti hiki huonyesha alama ya kipaumbele cha ukaguzi ya seli (0–1). Chaguo-msingi {defaultValue}.",
  "projectSettings.audioMedia.title": "Upakiaji wa sauti",
  "projectSettings.audioMedia.description": "Amua wakati rekodi za sauti zinapakuliwa kutoka hifadhi hadi kifaa hiki. Unaweza kubadili wakati wowote bila kurekodi upya — upakiaji wa baadaye pekee ndio unaoathiriwa.",
  "projectSettings.audioMedia.strategyStreamName": "Mtiririko",
  "projectSettings.audioMedia.strategyStreamDescription": "Cheza kutoka mtandao. Hakuna akiba kwenye kifaa hiki, na hakuna michoro ya mawimbi isipokuwa ukichagua kujumuishwa.",
  "projectSettings.audioMedia.strategyLazyName": "Inapohitajika (chaguo-msingi)",
  "projectSettings.audioMedia.strategyLazyDescription": "Pakua sauti ya seli unaposogeza hadi hapo au unapobonyeza cheza. Huweka nakala kwenye kifaa hiki.",
  "projectSettings.audioMedia.strategyEagerName": "Mapema",
  "projectSettings.audioMedia.strategyEagerDescription": "Leta mapema mchoro wa wimbi wa kila seli faili inapofunguka. Bora kwa ukaguzi nje ya mtandao.",
  "projectSettings.audioMedia.strategyManualName": "Kwa mkono",
  "projectSettings.audioMedia.strategyManualDescription": "Usipakue chochote kiotomatiki. Unabofya kitufe kwa kila seli ili kuipakia.",
  "projectSettings.sourceLink.description": "Mradi huu umeunganishwa na mradi wa chanzo wa juu. Seli za chanzo zinasomwa kutoka kwa mradi wa juu; watafsiri hufanya kazi upande wa lengo hapa.",
