  "terminology.livingMemory.title": "Kumbukumbu Hai",
  "terminology.livingMemory.introText": "Sauti na viwango vilivyowekwa vya timu yako — muktadha wa mradi ambao AI hutumia kwa kila rasimu mpya. Inakua kwa kila uthibitisho, sahihisho, na maagizo ambayo timu yako inaongeza.",
  "terminology.livingMemory.loadingValidatedTranslations": "Inapakia tafsiri zilizothibitishwa",
  "terminology.livingMemory.noValidatedTranslationsAria": "Hakuna tafsiri zilizothibitishwa",
  "terminology.livingMemory.noValidatedTranslationsTitle": "Bado hakuna tafsiri zilizothibitishwa",
  "terminology.livingMemory.noValidatedTranslationsDescription": "Watafsiri na wakaguzi wanapofikia kizingiti kinachohitajika cha uthibitisho kwenye seli, jozi hiyo ya chanzo → lengo inaonekana hapa. AI hutumia jozi hizi katika kila rasimu inayofuata.",
  "terminology.livingMemory.referenceAria": "Rejea: {reference}",
  "terminology.livingMemory.translationAria": "Tafsiri",
  "terminology.livingMemory.validatedByAria": "Imethibitishwa na: {validators}",
  "terminology.livingMemory.enterTextPlaceholder": "Weka matini…",
  "terminology.livingMemory.offlineTooltip": "Uko nje ya mtandao. Unganisha tena ili kuhariri.",
  "terminology.livingMemory.maintainerRequiredTooltip": "Kuhariri kunahitaji jukumu la Mtunzaji (600) au juu zaidi.",
  "terminology.livingMemory.contributorRequiredTooltip": "Hii inahitaji jukumu la Mchangiaji (400) au juu zaidi.",
