  "terminology.livingMemory.validatedCount": {"forms":{"one":"{count} imethibitishwa","other":"{count} zimethibitishwa"},"countVar":"count"},
  "terminology.livingMemory.goToTerminologyAria": "Nenda kwenye ukurasa wa Istilahi",
  "terminology.livingMemory.loadErrorPrefix": "Imeshindwa kupakia kumbukumbu kamili ya mradi: {message}",
  "terminology.livingMemory.instructionsTitle": "Maagizo",
  "terminology.livingMemory.instructionsDescription": "Iambie AI mradi huu unahusu nini — hadhira, toni, ukawaida, utunzaji maalum. Haya yanaonekana katika kila ombi la rasimu.",
  "terminology.livingMemory.instructionsPlaceholder": "Bado hakuna maagizo.",
  "terminology.livingMemory.instructionsExample": "\"Tafsiri kwa Kiswahili rasmi kwa hadhira ya watu wazima wanaojifunza kusoma na kuandika. Epuka istilahi za kiteolojia isipokuwa chanzo kimezitumia.\"",
  "terminology.livingMemory.standardsTitle": "Viwango",
  "terminology.livingMemory.standardsDescription": "Kanuni za ubora za mradi mzima ambazo AI hukagua rasimu zake nazo. Nasa maamuzi ambayo timu yako inaendelea kuyarejea.",
  "terminology.livingMemory.standardsPlaceholder": "Bado hakuna viwango.",
  "terminology.livingMemory.standardsExample": "\"Daima hifadhi majina halisi bila kutafsiriwa. Nambari katika chanzo lazima zionekane kama tarakimu katika lengo.\"",
  "terminology.livingMemory.recentExamplesTitle": "Mifano ya hivi karibuni",
  "terminology.livingMemory.recentExamplesDescription": "Jozi za chanzo→lengo zilizothibitishwa na watu ambazo AI hutumia kama mifano ya muktadha. Hizi ndizo tafsiri ambazo timu yako imekubaliana nazo.",
  "terminology.livingMemory.section.brief.title": "Muhtasari",
  "terminology.livingMemory.section.brief.description": "Si lazima — tafsiri hii ni ya nani na inapaswa kufanikisha nini. AI huisoma kama muktadha, si kama maagizo yake.",
  "terminology.livingMemory.section.brief.statusNone": "Haijaanzishwa",
  "terminology.livingMemory.section.brief.statusDraft": "Rasimu",
  "terminology.livingMemory.section.brief.statusComplete": "Imekamilika",
  "terminology.livingMemory.section.brief.statusNoneExplainer": "Si lazima unapotafsiri kwa mkono. Autopilot haitaanzishwa hadi angalau swali moja lijibiwe.",
  "terminology.livingMemory.section.brief.statusDraftExplainer": "Tayari inatumika — AI huandika rasimu kutoka kila jibu lililohifadhiwa hapa, na muhtasari huu unatosheleza ukaguzi wa kuanzisha Autopilot. “Rasimu” inamaanisha tu baadhi ya maswali hayajajibiwa au muhtasari umetangulia hariri yako ya hivi karibuni; hakuna cha kuidhinisha.",
  "terminology.livingMemory.section.brief.statusCompleteExplainer": "Kila swali limejibiwa na muhtasari unalingana na hariri yako ya hivi karibuni. AI huandika rasimu kutoka kwa muhtasari huu.",
  "terminology.livingMemory.section.instructions.description": "Jinsi AI inavyopaswa kutenda inapoandika rasimu, na ombi chaguo-msingi la utabiri",
  "terminology.livingMemory.section.instructions.entryCount": {"forms":{"one":"ingizo {count}","other":"maingizo {count}"},"countVar":"count"},
