  "harmonizer.flagLabel": "Kipatanishi",
  "harmonizer.flagDescription": "Hukagua jinsi seli zinavyounganika kuwa maandishi, kuanzia na nukuu zinazofunguka katika aya moja na zisizofungwa kamwe. Mapendekezo yanaonekana kando ya marekebisho mahiri, kwa hiyo marekebisho mahiri lazima yawe yamewashwa pia.",
  "harmonizer.popoverNote": "Imekaguliwa katika aya kadhaa dhidi ya chanzo na Jev.",
  "harmonizer.quotes.closeHere": "Nukuu inayofunguka katika {openedIn} inaishia hapa katika chanzo, kwa hiyo ifunge mwishoni mwa aya hii.",
  "harmonizer.reference.unclearSubject": "Mtu mwingine anafanya hili katika chanzo, lakini msomaji anayetoka {previous} anaweza kufikiri ni mtu yule yule. Fikiria kutaja ni nani.",
  "harmonizer.connective.reason": "Katika chanzo aya hii inatoa sababu ya {previous}, lakini kiunganishi hiki kinaiwasilisha kama matokeo.",
  "harmonizer.connective.inference": "Katika chanzo aya hii inatoa hitimisho kutoka {previous}, lakini kiunganishi hiki kinaiwasilisha kama sababu.",
  "harmonizer.connective.contrast": "Katika chanzo aya hii inatofautiana na {previous}, lakini kiunganishi hiki kinaiwasilisha kama matokeo.",
  "harmonizer.sentence.brokenCase": "Aya hii inamaliza sentensi yake hapa, lakini {next} inaendelea kwa herufi ndogo. Ama sentensi inaendelea, ama aya inayofuata inahitaji herufi kubwa.",
  "harmonizer.sentence.brokenOff": "Katika chanzo sentensi hii inaendelea hadi {next}, na hapa tafsiri inaishia kabla sentensi haijakamilika.",
  "harmonizer.sentence.runOn": "Sentensi ya chanzo inaishia katika aya hii na {next} inaanza sentensi mpya, lakini tafsiri haina uakifishaji wa kufunga hapa.",
  "harmonizer.reference.impliedSubject": "Mtu mwingine anafanya hili katika chanzo, lakini tafsiri haisemi ni nani, kwa hiyo msomaji anayetoka {previous} anaweza kudhani ni mtu yule yule. Fikiria kutaja ni nani.",
  "bibleData.experiment.label": "Viongezeo vya data ya Biblia",
  "bibleData.experiment.description": "Inaonyesha data ya Biblia wakati kitabu cha Biblia kimefunguliwa: nani anazungumza na nani, nani ni nani, muktadha wa lugha asilia, misaada ya tafsiri na ukaguzi wa data ya Biblia. Kwenye kifaa hiki pekee.",
  "bibleData.card.title": "Data ya Biblia",
  "bibleData.card.enableLabel": "Wezesha data ya Biblia",
  "bibleData.card.description": "Data ya marejeleo ya Biblia kutoka bibletranslation.org, iliyojengwa kutoka Macula, OpenText, ACAI na unfoldingWord. Inaendesha Nyenzo za aya, utafutaji wa Biblia, maulizo ya Biblia ya wakala na viongezeo vilivyo hapa chini.",
  "bibleData.enrichment.voices.label": "Wasemaji",
  "bibleData.enrichment.voices.description": "Inaonyesha nani anazungumza na nani katika kila seli, pamoja na mistari ya kando inayoonyesha nukuu inapofunguka na inapofungwa.",
  "bibleData.enrichment.whosWho.label": "Nani ni nani",
  "bibleData.enrichment.whosWho.description": "Hufuata kila mtu katika kifungu, pamoja na viwakilishi vinavyomrejelea na viima vinavyodokezwa.",
  "bibleData.enrichment.structure.label": "Muundo wa kifungu",
  "bibleData.enrichment.structure.description": "Inaonyesha vichwa vya sehemu, viashiria vya maswali na vya amri, na aya ambazo baadhi ya hati-mkono huacha nje.",
  "bibleData.enrichment.originalContext.label": "Muktadha wa lugha asilia",
  "bibleData.enrichment.originalContext.description": "Huongeza kichupo cha Muktadha chenye maneno ya Kigiriki au Kiebrania, glosi zao, na yule ambaye kila kiwakilishi kinamrejelea.",
  "bibleData.enrichment.helps.label": "Misaada ya tafsiri",
  "bibleData.enrichment.helps.description": "Inaonyesha Maelezo ya tafsiri na Maswali ya tafsiri kando ya maneno na aya yanayojadiliwa.",
  "bibleData.enrichment.terms.label": "Istilahi kuu",
  "bibleData.enrichment.terms.description": "Huashiria istilahi kuu katika maandishi ya chanzo na kuunganisha kila moja na makala yake ya Maneno ya tafsiri.",
  "bibleData.enrichment.places.label": "Maeneo na ramani",
  "bibleData.enrichment.places.description": "Inaonyesha maelezo mafupi na ramani kwa kila mahali panapotajwa na kifungu.",
  "bibleData.enrichment.checks.label": "Ukaguzi wa data ya Biblia",
  "bibleData.enrichment.checks.description": "Hukagua tafsiri dhidi ya mambo yanayojulikana, kama nani anasema na mahali nukuu inapoishia.",
  "bibleData.enrichment.autopilot.label": "Autopilot inatumia data ya Biblia",
  "bibleData.enrichment.autopilot.description": "Humipa Autopilot mambo haya inapoandika rasimu, na hukagua rasimu zake dhidi ya mambo hayo.",
  "bibleData.enrichment.switchOffReason": "Washa data ya Biblia ili kutumia viongezeo hivi.",
  "bibleData.enrichment.autopilotOffReason": "Autopilot imezimwa kwa mradi huu. Washa kwanza katika Majaribio.",
  "bibleData.enrichment.openBuiltinChecks": "Fungua ukaguzi uliojengwa ndani",
