  "bibleParticipants.p1.name": "Majina yamedumishwa",
  "bibleParticipants.p1.description": "Chanzo kinapomtaja mtu, tafsiri ina jina lililokubaliwa: uamuzi kama render.person.Peter, au ingizo la istilahi.",
  "bibleParticipants.p2.name": "Jina moja katika faili nzima",
  "bibleParticipants.p2.description": "Kila mtu, kundi au mahali hutumia jina lile lile katika kila aya inayotumia umbo lile lile la jina katika chanzo. Huendeshwa katika Kagua faili.",
  "bibleParticipants.p3.name": "Wenye majina sawa wametofautishwa",
  "bibleParticipants.p3.description": "Chanzo kinapomtaja mmoja kati ya watu kadhaa wenye jina sawa (Mariamu sita, Simoni tisa), tafsiri inatumia jina la mtu huyo, si la mtu mwingine mwenye jina hilo.",
  "bibleParticipants.p4.name": "Umbo la jina limedumishwa",
  "bibleParticipants.p4.description": "Chanzo kinapotumia umbo moja la jina (Kefa, si Simoni) na mradi una jina la kila umbo, tafsiri inatumia jina la umbo hilo.",
  "bibleParticipants.p5.name": "Hakuna majina ambayo chanzo hakina",
  "bibleParticipants.p5.description": "Tafsiri haitaji mtu yeyote ambaye chanzo cha aya hiyo hakimtaja, iwe kwa jina, kama kiwakilishi, au kama kiima cha kitenzi. Kiima cha aya iliyotangulia, au cha aya inayofuata, pia kinahesabika.",
  "bibleParticipants.p6.name": "Kiima kilichodokezwa kimetajwa sawasawa",
  "bibleParticipants.p6.description": "Chanzo kisipotaja mtu yeyote, na kinapodokeza tu nani anayetenda (“anasema”), jina ambalo tafsiri inaongeza ni jina la mtu huyo.",
  "bibleParticipants.p8.description": "Ikiwa kila “wewe” katika chanzo inamlenga mtu mmoja, au kila moja inawalenga wengi, tafsiri inatumia “wewe” ya idadi hiyo kutoka Wasifu wa lugha, na si ile nyingine.",
  "bibleParticipants.p9.name": "“sisi” ya jumuishi au ya kipekee",
  "bibleParticipants.p9.description": "“sisi” inapowajumuisha wanaozungumziwa, au inapowaacha nje, tafsiri inatumia “sisi” ya jumuishi au ya kipekee kutoka Wasifu wa lugha.",
  "bibleParticipants.p10.name": "Maumbo ya wawili, watatu na wachache",
  "bibleParticipants.p10.description": "Kiwakilishi kinaporejelea watu wawili, watatu au wachache, tafsiri inatumia umbo la idadi hiyo kutoka Wasifu wa lugha.",
  "bibleParticipants.p14.name": "Bwana na Roho",
  "bibleParticipants.p14.description": "κύριος inapomaanisha Yesu au Mungu, au πνεῦμα inapomaanisha Roho Mtakatifu, tafsiri inatumia utoaji wa mradi kwa kila moja.",
  "bibleParticipants.p15.name": "Herufi kubwa kwa Mungu",
  "bibleParticipants.p15.description": "Pale mwongozo wa mtindo unapotumia herufi kubwa kwa viwakilishi vya Mungu, Yesu na Roho Mtakatifu, viwakilishi hivyo vinaanza kwa herufi kubwa.",
  "bibleParticipants.x3.name": "Nukuu zinazorudiwa zinafanana",
  "bibleParticipants.x3.description": "Chanzo kinaporudia nukuu katika faili, tafsiri inaitoa kwa njia ile ile kila wakati. Huendeshwa katika Kagua faili.",
  "bibleParticipants.x4.name": "Maamuzi yamedumishwa",
  "bibleParticipants.x4.description": "Mradi umeamua ikiwa “sisi” katika kifungu inamjumuisha msikilizaji (uamuzi wa kipekee au jumuishi), kila “sisi” katika kifungu hicho inatumia umbo lililoamuliwa.",
  "bibleParticipants.needs.agreedNames": "Inahitaji: majina yaliyokubaliwa, kutoka maamuzi (render.…) au maingizo ya istilahi",
  "bibleParticipants.needs.nameForms": "Inahitaji: uamuzi kwa maumbo mawili ya jina moja (render.….form.…)",
  "bibleParticipants.needs.secondPersonForms": "Inahitaji: maumbo ya umoja na wingi ya “wewe” katika Wasifu wa lugha",
  "bibleParticipants.needs.secondPersonSame": "Haitumiki: katika Wasifu wa lugha, “wewe” ni sawa kwa mtu mmoja na kwa wengi",
  "bibleParticipants.needs.clusivityForms": "Inahitaji: maumbo ya jumuishi na ya kipekee ya “sisi” katika Wasifu wa lugha",
  "bibleParticipants.needs.clusivitySame": "Haitumiki: katika Wasifu wa lugha, “sisi” ni sawa pamoja na msikilizaji au bila yeye",
  "bibleParticipants.needs.groupNumberForms": "Inahitaji: maumbo ya wawili, watatu au wachache katika Wasifu wa lugha",
  "bibleParticipants.needs.groupNumberNone": "Haitumiki: Wasifu wa lugha hauna umbo la wawili, watatu wala wachache",
